base.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_availability_zones" "z" {}
module "m" {
  for_each = { a = length(data.aws_availability_zones.z.names), b = 1 }
  source   = "./m"
  n        = each.value
  name     = each.key
}

base.r/m/main.tf:
variable "n" {}
variable "name" {}
resource "aws_dynamodb_table" "t" {
  count    = var.n
  name     = "t-${var.name}"
  hash_key = "id"
}

